def transform(grid):
    # Expand each isolated marker by copying the bottom-row color sequence,
    # aligned so the marker retains its place in that sequence.
    h, w = len(grid), len(grid[0])
    seq = [v for v in grid[-1] if v]
    out = [row[:] for row in grid]
    if not seq:
        return out
    for r in range(h-1):
        for c, v in enumerate(grid[r]):
            if v:
                try:
                    k = seq.index(v)
                except ValueError:
                    continue
                start = c-k
                for j, x in enumerate(seq):
                    cc = start+j
                    if 0 <= cc < w:
                        out[r][cc] = x
    return out
