def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    templates = []
    # Nonzero runs along the top and bottom borders encode ordered sequences.
    for r in {0, h - 1}:
        c = 0
        while c < w:
            if grid[r][c] == 0:
                c += 1
                continue
            start = c
            seq = []
            while c < w and grid[r][c] != 0:
                seq.append(grid[r][c])
                c += 1
            if len(seq) > 1:
                templates.append(seq)
    for r in range(1, h - 1):
        for c in range(w):
            v = grid[r][c]
            if not v:
                continue
            for seq in templates:
                if v in seq:
                    start = c - seq.index(v)
                    for j, color in enumerate(seq):
                        cc = start + j
                        if 0 <= cc < w:
                            out[r][cc] = color
                    break
    return out
